UPDATE businesses SET description = 'JPS Moving is a Pretoria-based removals company operating from Mountain View, serving homes, offices and businesses across the city and beyond. The company provides local and long-distance moving services, including home removals, office removals and furniture removals, supported by packaging and storage solutions and its own transportation fleet. Clients range from individual households relocating within Pretoria to businesses coordinating office relocations, with the company handling the logistics of packing, loading, transporting and unpacking belongings for each move. JPS Moving offers storage options for customers who need to keep belongings secure between moves, along with packaging materials to protect items in transit. Over fourteen years in operation, the company has grown into a team of around ten staff members who carry out day-to-day moving operations. It is located at 1213 Daniel Street in Mountain View, Pretoria, placing it within reach of surrounding suburbs for both local jobs and moves further afield. JPS Moving''s services suit anyone needing a structured, supported move, whether relocating a family home, downsizing, or shifting an office setup, with transportation and storage handled as part of a single service.', description_enriched_at = datetime('now') WHERE slug = 'jps-moving-dorandia' AND description = 'JPS Moving is a Pretoria-based removals company offering local and long-distance moving services for homes, offices, complexes and storage, having grown from a single bakkie start-up in 2011.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
